const datos = items[0].json;

const url = String(datos.url || '').trim();
const evento = String(datos.evento || '').trim();

if (!url) {
  throw new Error('Te faltó pegar la URL del flujo.');
}

if (!url.startsWith('https://')) {
  throw new Error(
    'La URL tiene que empezar con https:// — Alegra no acepta http. ' +
      'Pegaste: ' + url
  );
}

if (url.includes('/webhook-test/')) {
  throw new Error(
    'Esa es la URL de prueba (dice /webhook-test/). Solo funciona mientras tienes ' +
      'el flujo abierto y le diste a "Listen for test event". Para registrarla en ' +
      'Alegra necesitas la URL de producción, la que dice /webhook/. La ves en el ' +
      'nodo del webhook, en la pestaña "Production URL", después de activar el flujo.'
  );
}

if (!url.includes('/webhook/')) {
  throw new Error(
    'Esa URL no parece la de un webhook de n8n. La correcta tiene /webhook/ en la ' +
      'mitad. Cópiala del nodo del webhook, pestaña "Production URL".'
  );
}

if (!evento) {
  throw new Error('Te faltó elegir el evento.');
}

return [{ json: { url, evento } }];

const pedido = $('Revisar lo que pegaste').first().json;
const respuesta = items[0].json;

const codigo = Number(respuesta.statusCode ?? 0);
const cuerpo = respuesta.body ?? respuesta;

const comoTexto = (x) => {
  if (x === null || x === undefined) return '';
  if (typeof x === 'string') return x;
  try {
    return JSON.stringify(x);
  } catch (e) {
    return String(x);
  }
};

const detalle = comoTexto(
  (cuerpo && (cuerpo.message || cuerpo.error)) || cuerpo
);

let quedo = false;
let titulo = '';
let explicacion = '';

if (codigo >= 200 && codigo < 300) {
  quedo = true;
  titulo = 'Listo, quedó registrado';
  explicacion =
    'Alegra ya sabe que cada vez que pase "' + pedido.evento + '" tiene que avisarle ' +
    'a tu flujo. Para probarlo, haz esa acción en Alegra y mira las ejecuciones del ' +
    'flujo en n8n.';
} else if (codigo === 401 || codigo === 403) {
  titulo = 'La credencial de Alegra no sirvió';
  explicacion =
    'Revisa la credencial "Alegra API": en User va el correo con el que entras a ' +
    'Alegra y en Password va tu token de la API, no tu contraseña.';
} else if (codigo === 400 || codigo === 409 || codigo === 422) {
  titulo = 'Alegra no lo aceptó';
  explicacion =
    'Casi siempre es porque esa misma URL ya está registrada para ese mismo evento. ' +
    'Alegra no acepta duplicados, así que si ves esto es probable que ya lo tuvieras ' +
    'listo de antes. La otra causa común es que la URL no sea alcanzable desde ' +
    'internet. Respuesta de Alegra: ' + detalle;
} else {
  titulo = 'Algo salió mal';
  explicacion =
    'Alegra respondió con el código ' + codigo + '. Respuesta: ' + detalle;
}

return [
  {
    json: {
      quedo,
      codigo,
      evento: pedido.evento,
      url: pedido.url,
      resultado: titulo,
      queSigue: explicacion,
      respuestaDeAlegra: detalle,
    },
  },
];
